head.script:
scwin.fn_SetPar, scwin.strCdSch;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.rdochange();
        window.document.body.scroll = "no";
        let arrPar = new Array();
        const parentWin = $c.frame.path("../");
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
        // fn_list_sync();
        txb_Search_1.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90200.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_Search_1_onkeydown
 * @description txb_Search_1 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_1_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            if (!await scwin.checkValues()) {
                return;
            }
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90200.txb_Search_1_onkeydown" });
    }
};

/**
 * @method
 * @name txb_Search_2_onkeydown
 * @description txb_Search_2 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Search_2_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            if (!await scwin.checkValues()) {
                return;
            }
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90200.txb_Search_2_onkeydown" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90200.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt.setValue("총 " + rowcount + " 건");
        if (scwin.strCdSch !== "") {
            for (let i = 1; i <= dts_List.getRowCount(); i++) {
                if (scwin.strCdSch === dts_List.getCellData(i, 1)) {
                    dts_List.setRowPosition(i, 0);
                    break;
                }
            }
            scwin.strCdSch = "";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90200.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name rdo_searchType_onselchange
 * @description rdo_searchType onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_searchType_onselchange = function() {
    try {
        scwin.rdochange();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS90200.rdo_searchType_onselchange" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        let arrPar = new Array();

        // if (fn_SetPar != undefined) {
        const ZIPCD = dts_List.getCellData(row, "ZIPCD");
        const ADDR = dts_List.getCellData(row, "ADDR");
        const ENG_ADDR = dts_List.getCellData(row, "ENG_ADDR");

        // arrPar[0] = dts_List.NameValue( dts_List.RowPosition, 'ZIPCD');
        // arrPar[1] = dts_List.NameValue( dts_List.RowPosition, 'ADDR');
        // arrPar[2] = dts_List.NameValue( dts_List.RowPosition, 'ZIPCD_SEQ');

        $c.frame.path("../").ins_popupRtn_cdnm2(ZIPCD, ADDR, ENG_ADDR);
        // }

        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90200.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (!await scwin.checkValues()) {
            return;
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90200.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90200.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
