 */
scwin.listSync = async function() {
    /*var url = "/listingCommon.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=listZipCd";
         url += "&inputMessageId=ZIPCD_OUT&outputMessageId=ZIPCD_OUT" ;
    	 url += "&SEARCHTYPE=" +getObjectValue(rdo_searchType) +"&SEARCHDTL_1=" +getObjectValue(txb_Search_1) + "&SEARCHDTL_2=" + getObjectValue(txb_Search_2) ;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();*/

    const sbmOptions = {
