///////// 5. 일반/업무 함수 영역 /////////
/**
     * @method
     * @name rdochange
     * @description rdochange 처리
     * @returns {void}
     * @hidden N
     */
scwin.rdochange = function() {
    if (rdo_searchType.getValue() === "1") {
        panel_1.show("");
        panel_2.hide();
        label_3.show("");
        label_9.hide();
    } else {
        panel_1.hide();
        panel_2.show("");
        label_3.hide();
        label_9.show("");
    }
};

/**
 * @method
 * @name checkValues
 * @description check Values 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValues = async function() {
    if (txb_Search_1.getValue().indexOf('%') !== -1 || txb_Search_2.getValue().indexOf('%') !== -1) {
        await $c.win.alert("'%' 문자는 입력할 수 없습니다.");
        return false;
    }

    // 도로명 검색
    if (rdo_searchType.getValue() === "1") {
        let searchWord = txb_Search_1.getValue();
        txb_Search_1.setValue(searchWord); // 공백제거한 값을 다시 입력
        if (searchWord.length < 2) {
            await $c.win.alert("도로명은 최소 2글자 이상 입력하세요.");
            txb_Search_1.focus();
            return false;
        } else {
            return true;
        }
        // 건물명 검색

    } else {
        let searchWord = txb_Search_2.getValue();
        txb_Search_2.setValue(searchWord); // 공백제거한 값을 다시 입력
        if (searchWord.length < 2) {
            await $c.win.alert("건물명은 최소 2글자 이상 입력하세요.");
            txb_Search_2.focus();
            return false;
        } else {
            return true;
        }
    }
};
